type RecordKeys4 struct {
	K0, K1, K2, K3 string
}

type RecordData4 struct {
	*RecordKeys4
	V0, V1, V2, V3 Value
}

func RecordShape4(keys *RecordKeys4, v0, v1, v2, v3 Value) Value {
	return Value{Type: TypeRecord4, UnsafePtr: unsafe.Pointer(&RecordData4{keys, v0, v1, v2, v3})}
