func RecordUpdate(orig Value, updates map[string]Value) Value {
	keys := make([]string, 0, len(updates))
	vals := make([]Value, 0, len(updates))
	for k, v := range updates {
		keys = append(keys, k)
		vals = append(vals, v)
	}
	return RecordUpdateDict(orig, keys, vals)
}

