`);
  const result = spawnSync('go', ['test', '-count=1', '.'], { cwd: directory, encoding: 'utf8', timeout: 60000,
    env: { ...process.env, GOWORK: 'off' } });
  assert.ifError(result.error);
  assert.equal(result.status, 0, result.stdout + result.stderr);
});

