#!/usr/bin/env python3
"""Measure allocations of frozen generated actions; never report timings."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import runpy
import subprocess
import sys

sys.dont_write_bytecode = True
ROOT = Path('/Users/0x1/Documents/htdocs/altbak.pub')
sys.path.insert(0, str(ROOT / 'bin/benchmark'))
from validate import CASES
from publish import ROWS
C = runpy.run_path(str(ROOT / 'bin/benchmark/compare-core.py'))
ADAPTER = runpy.run_path(str(Path(__file__).with_name('callback-adapter.py')))


def digest(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def write(path, value):
    Path(path).write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n')


def prepare(build):
    build = build.resolve()
    provenance = C['inspect_go'](build)
    output = build / 'output'
    adapter = ADAPTER['extract_callback_adapter'](build)
    sources = {p: p.read_text() for p in sorted((output / 'purescript').rglob('*.go'))}
    owners = {}
    for module in CASES:
        found = [p.parent.relative_to(output).as_posix() for p, text in sources.items()
                 if re.search(r'func Get_Test_' + re.escape(module) + r'_act\(', text)]
        if len(found) != 1:
            raise ValueError(f'Expected one generated action getter: {module}: {found}')
        owners[module] = found[0]
    packages = sorted(set(owners.values()))
    aliases = {name: 'p' + str(i) for i, name in enumerate(packages)}
    imports = '\n'.join(aliases[p] + ' "gopurs/output/' + p + '"' for p in packages)
    cases = ',\n'.join('{Name:' + json.dumps(label) + ',Expected:' + value + ',Get:'
                         + aliases[owners[module]] + '.Get_Test_' + module + '_act}'
                         for label, (module, value) in zip(ROWS, CASES.items()))
    source = '''package main
import("encoding/json";"os";"testing";r "gopurs/output/gopurs_runtime"
IMPORTS
)
var resultSink int
type Case struct {Name string; Expected int; Get func()r.Value}
type Result struct {NativeMetadata bool `json:"native_metadata"`; Path string `json:"path"`; Name string `json:"name"`; Expected int `json:"expected"`; Observed int `json:"observed"`; Allocs float64 `json:"allocations_per_action"`; Runs int `json:"measured_runs"`}
func main(){cases:=[]Case{CASES};out:=make([]Result,0,len(cases))
for _,item:=range cases{action:=item.Get();for _,path:=range []string{"ffi_conversion","forced_fallback"}{chosen:=action;if path=="forced_fallback"{chosen=r.Func(func(_ r.Value)r.Value{return r.Apply(action,r.Value{})})};_,native:=r.FunctionData[func() int64](chosen);if path=="forced_fallback"&&native{panic("fallback unexpectedly has native metadata")};callback:=convertCallback(chosen);call:=func(){resultSink=callback()}
call();if resultSink!=item.Expected{panic("incorrect action result")}
allocs:=testing.AllocsPerRun(100,call)
if resultSink!=item.Expected{panic("incorrect repeated action result")}
out=append(out,Result{NativeMetadata:native,Path:path,Name:item.Name,Expected:item.Expected,Observed:resultSink,Allocs:allocs,Runs:100})}}
if err:=json.NewEncoder(os.Stdout).Encode(out);err!=nil{panic(err)}}
'''.replace('IMPORTS', imports).replace('CASES', cases) + adapter['source']
    return {'provenance': provenance, 'output': output, 'source': source,
            'adapter': adapter, 'source_sha256': {str(p): digest(p) for p in sources}}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--before', type=Path, required=True)
    parser.add_argument('--after', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--execute', action='store_true')
    args = parser.parse_args()
    plans = {name: prepare(path) for name, path in [('before', args.before), ('after', args.after)]}
    for field in ['profile', 'toolchain']:
        if plans['before']['provenance'][field] != plans['after']['provenance'][field]:
            raise ValueError('Before/after configurations differ: ' + field)
    if not args.execute:
        print(json.dumps({'validated': True, 'cases_per_build': 14, 'callback_paths_per_case': 2, 'measured_runs_per_case': 100,
                          'timings_reported': False}, indent=2))
        return
    directory = args.output.resolve()
    directory.mkdir(parents=True, exist_ok=False)
    env = dict(os.environ, GOWORK='off', GOGC='800')
    env.pop('PPROF', None)
    env.pop('GOMAXPROCS', None)
    results, evidence = {}, {}
    for name, plan in plans.items():
        source = directory / (name + '-main.go')
        source.write_text(plan['source'])
        command = ['go', 'run', '-pgo=off', str(source)]
        result = subprocess.run(command, cwd=plan['output'], env=env, capture_output=True,
                                text=True, timeout=120)
        (directory / (name + '.stdout')).write_text(result.stdout)
        (directory / (name + '.stderr')).write_text(result.stderr)
        if result.returncode or result.stderr:
            raise RuntimeError('Allocation probe failed: ' + name + '\n' + result.stderr)
        rows = json.loads(result.stdout)
        expected_rows = [(name, path) for name in ROWS for path in ['ffi_conversion', 'forced_fallback']]
        if len(rows) != 28 or [(row['name'], row['path']) for row in rows] != expected_rows:
            raise ValueError('Missing or reordered action results')
        for row, expected in zip(rows, [value for value in CASES.values() for _ in range(2)]):
            if row['observed'] != int(expected) or row['expected'] != int(expected):
                raise ValueError('Invalid action oracle')
        C['verify_hashes'](plan['source_sha256'])
        C['verify_hashes'](plan['provenance']['payload_sha256'])
        results[name] = {path: {row['name']: row['allocations_per_action'] for row in rows if row['path'] == path} for path in ['ffi_conversion', 'forced_fallback']}
        evidence[name] = {'build': plan['provenance']['cwd'], 'command': command,
                          'cwd': str(plan['output']), 'manifest_sha256': plan['provenance']['manifest_sha256'],
                          'binary_sha256': plan['provenance']['manifest']['binary_sha256'],
                          'generated_sources_sha256': plan['source_sha256'], 'main_sha256': digest(source),
                          'adapter': plan['adapter'], 'results': rows}
    report = {'scope': 'Allocation diagnostic only, excluded from all official timing samples',
              'protocol': 'Actual compiled getters and the exact generated MeasureBatch FFI conversion, including a separate forced metadata-free fallback; conversion resolved once outside the measured callback; unchanged opaque boundary; testing.AllocsPerRun(100) after initialization and warm-up.',
              'GOGC': '800', 'GOMAXPROCS': 'testing.AllocsPerRun temporarily uses one thread',
              'source_and_harness_mutated': False, 'timings_reported': False,
              'oracles_verified': 56, 'allocations_per_action': results, 'builds': evidence,
              'script_sha256': digest(__file__)}
    write(directory / 'results.json', report)
    print(json.dumps({'allocations_per_action': results, 'oracles_verified': 56,
                      'timings_reported': False}, indent=2))


if __name__ == '__main__':
    main()

