#!/usr/bin/env python3
"""One isolated AB/BA/AB counter-measurement of all AppAll regressions above 5%."""
from pathlib import Path
import hashlib,json,math,os,re,runpy,statistics,subprocess,sys
from datetime import datetime,timezone
ROOT=Path('/Users/0x1/Documents/htdocs/altbak.pub')
WORK=ROOT/'var/benchmark/go-native-callbacks-20261126'
PROOF=WORK/'proofs/isolated-regressions'
HELPERS=runpy.run_path(str(Path(__file__).with_name('compare-generated.py')))
sha=lambda path:hashlib.sha256(Path(path).read_bytes()).hexdigest()
primary=WORK/'campaign/results.json'
primary_sha=sha(primary)
original_report=json.loads(primary.read_text())
labels=[row['case'] for row in original_report['all_case_regressions_over_5_percent']]
if not labels: raise ValueError('No primary regression above 5%; diagnostics are unnecessary')
keys=[re.sub(r'[^a-zA-Z0-9_-]+','-',label) for label in labels]
cases=[]
for key,label in zip(keys,labels):
 row=original_report['all_campaign']['all_tests'][label]
 cases.append({'key':key,'label':label,'module':row['module'].replace('.','_'),'getter':'Get_'+row['module'].replace('.','_')+('_act' if label in original_report['primary_times_us']['after'] else '_prepare'),'expected':row['expected'],'prepare':label not in original_report['primary_times_us']['after']})
builds={'before':ROOT/'var/benchmark/go-ffi-calls-20261126/after-all','after':WORK/'after-all'}
env=dict(os.environ,GOGC='800',GOWORK='off')
for key in ['GOMAXPROCS','PPROF']:env.pop(key,None)
PROOF.mkdir(parents=True,exist_ok=False)
(PROOF/'inputs.json').write_text(json.dumps(cases,indent=2)+'\n')
inventories={side:HELPERS['inventory'](path) for side,path in builds.items()}
originals={side:inventory['provenance'] for side,inventory in inventories.items()}
commands={};probe_sources={};comparisons={}
for case in cases:
 key=case['key']; commands[key]={};probe_sources[key]={}
 names={'Bench.go','Bench_ffi.go','Effect_Console.go','Effect_Console_ffi.go',case['module']+'.go'}
 comparisons[key]={side:{name:{'sha256':hashlib.sha256(body).hexdigest(),'source':body.decode()} for name,body in inventory['sections'].items() if Path(name).name in names} for side,inventory in inventories.items()}
 for side,inventory in inventories.items():
  owner=lambda declaration:[str(Path(name).parent) for name,body in inventory['sections'].items() if re.search(rb'func '+declaration.encode()+rb'\(',body)]
  action=owner(case['getter']); bench=owner('Call_Bench_runBench'); console=owner('Get_Effect_Console_log')
  assert len(action)==len(bench)==len(console)==1,(case,side,action,bench,console)
  packages=sorted(set(action+bench+console));aliases={name:'p'+str(i) for i,name in enumerate(packages)}
  imports='; '.join(aliases[name]+' "gopurs/output/'+name+'"' for name in packages)
  act=aliases[action[0]]+'.'+case['getter']+'()'
  if case['prepare']:act='r.Apply('+act+',r.Value{})'
  main=f'''package main
import(r "gopurs/output/gopurs_runtime"; {imports})
func main(){{
 act:={act}
 for i:=0;i<3;i++{{if value:=r.Apply(act,r.Value{{}});value.Type!=r.TypeInt||value.IntVal!={case['expected']}{{panic("invalid global warmup result")}}}}
 describe:=r.Apply({aliases[console[0]]}.Get_Effect_Console_log(),r.Str("{case['label']}"))
 r.Apply({aliases[bench[0]]}.Call_Bench_runBench(describe,act),r.Value{{}})
}}
'''
  source=PROOF/(key+'-'+side+'-main.go');source.write_text(main);probe_sources[key][side]=sha(source)
  command=['go','build','-pgo=off','-o',str(PROOF/(key+'-'+side+'-probe')),str(source)]
  process=subprocess.run(command,cwd=builds[side]/'output',env=env,text=True,capture_output=True)
  (PROOF/(key+'-'+side+'-build.stdout')).write_text(process.stdout);(PROOF/(key+'-'+side+'-build.stderr')).write_text(process.stderr)
  process.check_returncode();assert not process.stderr;commands[key][side]=command;print('Built',key,side,flush=True)
(PROOF/'generated-comparison.json').write_text(json.dumps(comparisons,indent=2)+'\n')
# All diagnostic builds must finish before the first timed diagnostic starts.
sys.path.insert(0,str(ROOT/'bin/benchmark'))
from validate import ROW
order=['before','after','after','before','before','after'];results={}
for case in cases:
 key=case['key'];samples={'before':[],'after':[]};runs=[]
 for index,side in enumerate(order,1):
  process=subprocess.run([str(PROOF/(key+'-'+side+'-probe'))],cwd=builds[side]/'output',env=env,text=True,capture_output=True,timeout=60)
  stem=f'{key}-{index}-{side}';(PROOF/(stem+'.stdout')).write_text(process.stdout);(PROOF/(stem+'.stderr')).write_text(process.stderr)
  process.check_returncode();assert not process.stderr;rows=ROW.findall(process.stdout)
  assert len(rows)==1 and process.stdout.count('(Test)')==1
  label,value,elapsed=rows[0];assert label.strip()==case['label'] and value.strip()==str(case['expected'])
  value=float(elapsed);assert math.isfinite(value) and value>0
  batches=[int(n) for n in re.findall(r'^Batch iterations: (\d+)$',process.stdout,re.M)]
  assert len(batches)==1 and 0<batches[0]<=16777216 and not batches[0]&(batches[0]-1)
  samples[side].append(value);runs.append({'variant':side,'time_us':value,'batch_iterations':batches[0],'stdout':process.stdout,'stderr':process.stderr})
  print(stem,value,'us',flush=True)
 medians={side:statistics.median(values) for side,values in samples.items()}
 results[key]={'case':case['label'],'expected':case['expected'],'original_builds':originals,'commands':commands[key],'main_sha256':probe_sources[key],'probe_binary_sha256':{side:sha(PROOF/(key+'-'+side+'-probe')) for side in samples},'order':order,'samples_us':samples,'medians_us':medians,'change_percent':100*(medians['after']/medians['before']-1),'runs':runs}
for side,path in builds.items():assert originals[side]==HELPERS['inventory'](path)['provenance']
assert sha(primary)==primary_sha
report={'measured_at_utc':datetime.now(timezone.utc).isoformat(),'scope':'Separate diagnostics only; every primary campaign sample and aggregate remains unchanged','protocol':'Three processes per variant AB/BA/AB per case; actual compiled getters and Bench.runBench; three global warmups then unchanged calibration/minimum-of-ten harness; all probe builds complete before measurements','GOGC':'800','GOMAXPROCS':'default','host_isolated':False,'source_comparison':'generated-comparison.json','script_sha256':sha(__file__),'primary_campaign_sha256':primary_sha,'cases':results,'oracles_verified':6*len(cases),'original_generated_sources_and_binaries_unchanged':True}
(PROOF/'results.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({key:{name:row[name] for name in ['case','samples_us','medians_us','change_percent']} for key,row in results.items()},indent=2))

