#!/usr/bin/env python3
"""Retain target action/FFI source and assembly from both measured App builds."""
import argparse
import hashlib
import json
from pathlib import Path
import re
import subprocess

ROOT = Path('/Users/0x1/Documents/htdocs/altbak.pub')
WORK = ROOT / 'var/benchmark/go-native-callbacks-20261126'
TARGETS = {'Bench.go', 'Bench_ffi.go', 'Test_Church.go', 'Test_StateMonad.go', 'Test_LazyEvaluation.go',
           'Test_Polymorphism.go', 'Test_RowToList.go', 'Test_ListOps.go', 'Test_ArrayOps.go'}
ASM = r'Get_Test_(Church|StateMonad|LazyEvaluation|Polymorphism|RowToList|ListOps|ArrayOps)_act|Call_Bench_runBench|Bench_MeasureBatch|Bench_Opaque_runEffectWorker|opaqueValue|gopurs_runtime.Apply$|FunctionData|^runtime.convT$'


def sha(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--before', type=Path, default=ROOT / 'var/benchmark/go-ffi-calls-20261126/after-core')
    parser.add_argument('--after', type=Path, default=WORK / 'after-core')
    parser.add_argument('--output', type=Path, default=WORK / 'proofs/production-generated')
    args = parser.parse_args()
    args.output.mkdir(parents=True, exist_ok=False)
    manifest = {'script_sha256': sha(Path(__file__)), 'targets': sorted(TARGETS), 'builds': {}}
    for variant, directory in [('before', args.before), ('after', args.after)]:
        directory = directory.resolve()
        binary = directory / 'benchmark'
        build = json.loads((directory / 'manifest.json').read_text())
        if sha(binary) != build['binary_sha256']:
            raise ValueError('Benchmark binary differs from manifest: ' + variant)
        files = {}
        for source in sorted((directory / 'output/purescript').rglob('*.go')):
            content = source.read_bytes()
            markers = list(re.finditer(rb'^// gopurs-source-v1: ([0-9a-f]+)\r?\n', content, re.M))
            for i, marker in enumerate(markers):
                name = bytes.fromhex(marker[1].decode()).decode()
                if Path(name).name not in TARGETS:
                    continue
                end = markers[i + 1].start() if i + 1 < len(markers) else len(content)
                fragment = content[marker.end():end]
                target = args.output / (variant + '-' + source.parent.name + '-' + Path(name).name)
                target.write_bytes(fragment)
                files[target.name] = {'source': str(source), 'source_sha256': sha(source),
                                      'section': name, 'sha256': sha(target)}
        assembly = subprocess.check_output(['go', 'tool', 'objdump', '-s', ASM, str(binary)])
        if not assembly or not files:
            raise ValueError('Expected generated source and assembly evidence')
        asm_file = args.output / (variant + '-production-assembly.txt')
        asm_file.write_bytes(assembly)
        manifest['builds'][variant] = {'directory': str(directory), 'binary_sha256': sha(binary),
                                      'manifest_sha256': sha(directory / 'manifest.json'),
                                      'files': files, 'assembly_sha256': sha(asm_file)}
        if variant == 'after':
            command = ['go', 'tool', 'objdump', '-s', 'Get___gopurs_ffi_argument', str(binary)]
            getter_assembly = subprocess.check_output(command)
            if not getter_assembly:
                raise ValueError('Expected cached argument getters in optimized binary')
            getter_file = args.output / 'after-cache-getters-assembly.txt'
            getter_file.write_bytes(getter_assembly)
            manifest['builds'][variant]['cache_getter_assembly'] = {
                'file': getter_file.name, 'sha256': sha(getter_file),
                'command': command, 'binary_sha256': sha(binary)}
    (args.output / 'manifest.json').write_text(json.dumps(manifest, indent=2) + '\n')
    print(json.dumps({key: {'sections': len(value['files']), 'binary_sha256': value['binary_sha256']}
                      for key, value in manifest['builds'].items()}, indent=2))


if __name__ == '__main__':
    main()

