#!/usr/bin/env python3
"""Review every generated declaration, with native-callback-specific proofs.

No compilation or execution of generated code. Unlike the earlier cache audit,
this verifies two identical effect bodies, removing only the final canonical
Int constructor from the native copy. It verifies the complete old/new FFI
adapter shapes and compares all remaining declarations after namespace mapping.
"""
import argparse
from collections import Counter
import hashlib
import json
from pathlib import Path
import re
import runpy

HERE = Path(__file__).resolve().parent
WORK = HERE.parents[1]
ROOT = WORK.parents[2]
LIB = runpy.run_path(str(HERE / 'compare-generated.py'))
LEX = re.compile(r'//[^\n]*|/\*.*?\*/|"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\'|`[^`]*`|[A-Za-z_]\w*|(?:0[xX][\da-fA-F]+|\d+(?:\.\d*)?(?:[eE][+-]?\d+)?)|[^\s]', re.S)
PAIRS = {'(': ')', '[': ']', '{': '}'}


def require(condition, message):
    if not condition:
        raise ValueError(message)


def sha(value):
    return hashlib.sha256(value).hexdigest()


def lex(text):
    return [m.group() for m in LEX.finditer(text) if not m.group().startswith(('//', '/*'))]


def matching(tokens, start):
    require(tokens[start] in PAIRS, 'Expected an opening delimiter')
    stack = []
    for index in range(start, len(tokens)):
        token = tokens[index]
        if token in PAIRS:
            stack.append(PAIRS[token])
        elif token in PAIRS.values():
            require(stack and stack.pop() == token, 'Unbalanced Go delimiters')
            if not stack:
                return index
    raise ValueError('Unclosed Go delimiter')


def arguments(tokens):
    result, begin, index = [], 0, 0
    while index < len(tokens):
        if tokens[index] in PAIRS:
            index = matching(tokens, index)
        elif tokens[index] == ',':
            result.append(tokens[begin:index]); begin = index + 1
        index += 1
    return result + [tokens[begin:]]


def function(tokens, start=0):
    if tokens[start:start+2] != ['func', '(']:
        return None
    params_end = matching(tokens, start + 1)
    body_start = params_end + 1
    while body_start < len(tokens) and tokens[body_start] != '{':
        if tokens[body_start] in ('(', '['):
            body_start = matching(tokens, body_start)
        body_start += 1
    if body_start == len(tokens):
        return None
    end = matching(tokens, body_start)
    return (tokens[start+2:params_end], tokens[params_end+1:body_start],
            tokens[body_start+1:end], end + 1)


def namespaces(tokens, aliases):
    result, index = [], 0
    while index < len(tokens):
        if index + 1 < len(tokens) and tokens[index+1] == '.' and tokens[index] in aliases:
            name = aliases[tokens[index]]
            if name:
                result.extend([name, '.'])
            index += 2
        else:
            result.append(tokens[index]); index += 1
    return result


def declarations(inventory):
    result = []
    for path, raw in inventory['sections'].items():
        header = inventory['headers'][str(Path(path).parent / '0_gopurs_package.go')].decode()
        aliases = {alias: ('RUNTIME' if name.endswith('/gopurs_runtime') else ''
                           if '/purescript/' in name else '@' + name)
                   for alias, name in re.findall(r'^\s*(\w+) "([^"\n]+)"', header, re.M)}
        text = raw.decode()
        matches = [m for m in LEX.finditer(text) if not m.group().startswith(('//', '/*'))]
        starts, depth = [], 0
        for index, match in enumerate(matches):
            token = match.group()
            if depth == 0 and token in ('func', 'var', 'const', 'type') and (match.start() == 0 or text[match.start()-1] == '\n'):
                starts.append(index)
            if token in PAIRS: depth += 1
            if token in PAIRS.values(): depth -= 1
        require(not matches or starts and starts[0] == 0, 'Unparsed generated section: ' + path)
        require(depth == 0, 'Unbalanced generated section: ' + path)
        for index, start in enumerate(starts):
            end = starts[index+1] if index+1 < len(starts) else len(matches)
            result.append({'source': path, 'tokens': namespaces([m.group() for m in matches[start:end]], aliases)})
    return result


def without_final_int(body):
    index, last_return = 0, None
    while index < len(body):
        if body[index] in PAIRS:
            index = matching(body, index)
        elif body[index] == 'return':
            last_return = index
        index += 1
    require(last_return is not None, 'No final boxed return in native-entry candidate')
    tail = body[last_return:]
    require(tail[:5] == ['return', 'RUNTIME', '.', 'Int', '(']
            and matching(tail, 4) == len(tail)-1, 'Native entry does not remove exactly the final canonical Int constructor')
    return body[:last_return] + ['return'] + tail[5:-1]


def native_entries(tokens, source):
    result, entries, index = [], [], 0
    prefix = ['RUNTIME', '.', 'WithFunctionData', '(']
    while index < len(tokens):
        if tokens[index:index+4] == prefix:
            end = matching(tokens, index+3)
            args = arguments(tokens[index+4:end])
            native = function(args[1]) if len(args) == 2 else None
            if native and native[0] == [] and native[1] == ['int64'] and native[3] == len(args[1]):
                ordinary = args[0]
                require(ordinary[:4] == ['RUNTIME', '.', 'Func', '(']
                        and matching(ordinary, 3) == len(ordinary)-1, 'Unexpected ordinary entry for native Effect Int')
                boxed = function(ordinary[4:-1])
                require(boxed and boxed[0] == ['_', 'RUNTIME', '.', 'Value']
                        and boxed[1] == ['RUNTIME', '.', 'Value'] and boxed[3] == len(ordinary)-5,
                        'Unexpected boxed Effect Int signature')
                require(without_final_int(boxed[2]) == native[2],
                        'Native effect body differs beyond its final Int constructor: ' + source)
                entries.append({'source': source, 'body_tokens': len(boxed[2]),
                                'boxed_body_sha256': sha(' '.join(boxed[2]).encode()),
                                'native_body_sha256': sha(' '.join(native[2]).encode())})
                result.extend(ordinary); index = end + 1; continue
        result.append(tokens[index]); index += 1
    return result, entries


def old_adapter(params, returns, body):
    if params or returns not in (['int'], ['int64']) or len(body) < 10:
        return None
    temporary = body[0]
    if not re.fullmatch(r'inner_res\d+', temporary) or body[1:7] != [':', '=', 'RUNTIME', '.', 'Apply', '(']:
        return None
    close = matching(body, 6)
    args = arguments(body[7:close])
    expected_tail = lex('return RUNTIME.Unbox[' + returns[0] + '](' + temporary + ')')
    if len(args) != 2 or args[1] != lex('RUNTIME.Value{}') or body[close+1:] != expected_tail:
        return None
    return args[0]


def new_adapter_signature(native):
    fast = '__gopurs_native_action' if native == 'int64' else 'func() int { return int(__gopurs_native_action()) }'
    return lex('''func(__gopurs_action RUNTIME.Value) func() ''' + native + ''' {
      if __gopurs_native_action, ok := RUNTIME.FunctionData[func() int64](__gopurs_action); ok { return ''' + fast + ''' }
      return func() ''' + native + ''' { return RUNTIME.Unbox[''' + native + '''](RUNTIME.Apply(__gopurs_action, RUNTIME.Value{})) }
    }''')


def ffi_adapters(tokens, source):
    if not source.endswith('_ffi.go'):
        return tokens, []
    result, adapters, index = [], [], 0
    while index < len(tokens):
        literal = function(tokens, index) if tokens[index:index+2] == ['func', '('] else None
        if literal:
            params, returns, body, end = literal
            action = old_adapter(params, returns, body)
            kind = 'ordinary'
            if action is None and params == lex('__gopurs_action RUNTIME.Value'):
                for native in ('int', 'int64'):
                    if tokens[index:end] == new_adapter_signature(native):
                        require(tokens[end] == '(', 'Native FFI resolver must capture its action immediately')
                        call_end = matching(tokens, end)
                        args = arguments(tokens[end+1:call_end])
                        require(len(args) == 1 and args[0], 'Native FFI resolver must evaluate one action expression')
                        action, returns, end, kind = args[0], [native], call_end+1, 'native'
                        break
            if action is not None:
                result.extend(['EFFECT_INT_ADAPTER', returns[0], '('] + action + [')'])
                adapters.append({'source': source, 'kind': kind, 'native_type': returns[0], 'action': ' '.join(action)})
                index = end; continue
        result.append(tokens[index]); index += 1
    return result, adapters


def normalized(inventory):
    rows, entries, adapters = [], [], []
    for declaration in declarations(inventory):
        tokens, added = native_entries(declaration['tokens'], declaration['source'])
        entries.extend(added)
        tokens, converted = ffi_adapters(tokens, declaration['source'])
        adapters.extend(converted)
        rows.append({'source': declaration['source'], 'tokens': ' '.join(tokens)})
    return rows, entries, adapters


def compare(before_path, after_path):
    before, after = LIB['inventory'](before_path), LIB['inventory'](after_path)
    old, old_entries, old_adapters = normalized(before)
    new, new_entries, new_adapters = normalized(after)
    a, b = Counter(row['tokens'] for row in old), Counter(row['tokens'] for row in new)
    removed, added = list((a-b).elements()), list((b-a).elements())
    runtime = 'gopurs_runtime/runtime.go'
    poc = (WORK / 'proofs/probe-callbacks/runtime-unary.go').read_text()
    runtime_matches = lex(after['standalone'][runtime].decode()) == lex(poc)
    others = {name: before['standalone'].get(name) == after['standalone'].get(name)
              for name in set(before['standalone']) | set(after['standalone']) if name != runtime}
    headers = {name: before['headers'].get(name) == after['headers'].get(name)
               for name in set(before['headers']) | set(after['headers'])}
    directive = re.compile(rb'^\s*//go:[^\n]+', re.M)
    directives_equal = Counter(match.strip() for data in before['sections'].values() for match in directive.findall(data)) == Counter(match.strip() for data in after['sections'].values() for match in directive.findall(data))
    return {'status': 'passed' if not removed and not added and runtime_matches and all(others.values()) and all(headers.values()) and directives_equal else 'needs-review',
            'builds': {'before': before['provenance'], 'after': after['provenance']},
            'declaration_counts': {'before': len(old), 'after': len(new)},
            'native_entries': {'before': old_entries, 'after': new_entries},
            'ffi_adapters': {'before': old_adapters, 'after': new_adapters},
            'runtime_matches_exact_poc_tokens': runtime_matches,
            'other_files_unchanged': others, 'headers_unchanged': headers,
            'go_directives_unchanged': directives_equal,
            'unexplained_removed_declarations': removed, 'unexplained_added_declarations': added}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    prior = ROOT / 'var/benchmark/go-ffi-calls-20261126'
    parser.add_argument('--before-core', type=Path, default=prior / 'after-core')
    parser.add_argument('--after-core', type=Path, default=WORK / 'after-core')
    parser.add_argument('--before-all', type=Path, default=prior / 'after-all')
    parser.add_argument('--after-all', type=Path, default=WORK / 'after-all')
    parser.add_argument('--output', type=Path, default=WORK / 'proofs/generated-review.json')
    args = parser.parse_args()
    result = {'script_sha256': sha(Path(__file__).read_bytes()),
              'method': 'Tokenize declarations preserving identifiers, literals and multiplicity; normalize only import aliases/package location, verified duplicate native bodies with final Int removed, and exact old/new Effect Int FFI adapters. Runtime must match the isolated POC in full; all other files/imports/directives must be unchanged.',
              'limitations': 'Source equivalence audit for the declared transformations; package placement and machine-code layout can still affect performance. Unexpected declarations are retained in full and fail the review.',
              'core': compare(args.before_core, args.after_core), 'all': compare(args.before_all, args.after_all)}
    args.output.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
    summary = {scope: {'status': result[scope]['status'], 'native_entries': len(result[scope]['native_entries']['after']),
                       'new_ffi_adapters': sum(row['kind']=='native' for row in result[scope]['ffi_adapters']['after']),
                       'unexplained_removed': len(result[scope]['unexplained_removed_declarations']),
                       'unexplained_added': len(result[scope]['unexplained_added_declarations'])} for scope in ('core','all')}
    print(json.dumps(summary,indent=2))
    require(all(result[scope]['status']=='passed' for scope in ('core','all')), 'Generated differences need review: '+str(args.output))


if __name__ == '__main__':
    main()

