import { readFileSync } from "node:fs";
import "./wasm_exec.js";

async function run() {
  const go = new globalThis.Go();
  const wasmBuffer = readFileSync(new URL("./ffi_gen.wasm", import.meta.url));
  const result = await WebAssembly.instantiate(wasmBuffer, go.importObject);
  // The Go main registers parseFFI, then waits for calls indefinitely.
  // Observe startup failures without waiting for the runtime to finish.
  go.run(result.instance).catch(fail);
  const content = readFileSync(0, "utf8");
  const prefix = process.argv[2];
  const response =
    prefix === "--optimize-generated-source"
      ? globalThis.optimizeGeneratedSource(process.argv[3], content)
      : prefix === "--share-record-shapes"
      ? globalThis.shareRecordShapes(process.argv[3], content)
      : prefix === "--package-source"
      ? globalThis.packageGoSource(content)
      : prefix === "--bind-source"
        ? globalThis.bindGoSource(content)
        : prefix === undefined
          ? globalThis.parseFFI(content)
          : globalThis.parseFFI(content, prefix);
  if (!response || typeof response.json !== "string" || typeof response.error !== "string") {
    throw new Error("Invalid Go FFI parser response; rebuild with npm run build:ffi");
  }
  if (response.error) {
    throw new Error(`Go FFI parse failed: ${response.error}`);
  }
  process.stdout.write(response.json + (["--share-record-shapes", "--optimize-generated-source"].includes(prefix) ? "" : "\n"), () => process.exit(0));
}

function fail(error) {
  // Go may still be waiting; an exitCode alone would leave it alive.
  process.stderr.write(`FFI runner: ${error.message}\n`, () => process.exit(1));
}

run().catch(fail);

