manifest=json.loads((HERE/'manifest.json').read_text())
for path,digest in manifest['original_files_sha256'].items():
 assert hashlib.sha256(Path(path).read_bytes()).hexdigest()==digest,path
assembly=(HERE/'unary-opaque-assembly.txt').read_text()
sections={text.splitlines()[0].split('(')[0]:text for text in assembly.split('TEXT ')[1:]}
worker=next(value for name,value in sections.items() if name.endswith('Bench_Opaque_runEffectWorker'))
