#!/usr/bin/env python3
"""Three short alternate-order processes; frozen-source checks before and after."""
import hashlib,json,os,statistics,subprocess
from pathlib import Path
HERE=Path(__file__).resolve().parent
manifest=json.loads((HERE/'manifest.json').read_text())
def verify():
 for path,digest in manifest['original_files_sha256'].items():
  if hashlib.sha256(Path(path).read_bytes()).hexdigest()!=digest:raise ValueError('Frozen input changed: '+path)
verify()
env=dict(os.environ,GOGC='800');env.pop('GOMAXPROCS',None);env.pop('PPROF',None)
runs=[]
for index in range(1,4):
 result=subprocess.run([str(HERE/'probe-preserve'),str(index)],capture_output=True,text=True,env=env,check=True,timeout=90)
 (HERE/f'preserve-{index}.stdout').write_text(result.stdout);(HERE/f'preserve-{index}.stderr').write_text(result.stderr)
 values=[json.loads(line) for line in result.stdout.splitlines()]
 assert len(values)==9 and all(row['actual']==row['expected'] for row in values)
 runs.append(values)
 print('Process',index,'9 action outputs + 6 variable-input effects + 9 preserved-entry outputs verified',flush=True)
verify()
summary={}
for name in ['State','RowToList','Church']:
 summary[name]={}
 for variant in ['current','ordinary-preserved','ordinary-native-wrapper']:
  rows=[next(row for row in run if row['case']==name and row['variant']==variant) for run in runs]
  summary[name][variant]={'median_ns':statistics.median(row['time_ns'] for row in rows),'process_ns':[row['time_ns'] for row in rows],'allocations_per_action':[row['allocations_per_action'] for row in rows]}
 summary[name]['preserved_gain_percent']=100*(1-summary[name]['ordinary-preserved']['median_ns']/summary[name]['current']['median_ns'])
root=HERE.parents[4]
baseline=json.loads((root/'var/benchmark/go-ffi-calls-20261126/campaign/results.json').read_text())
reported={short:1000*baseline['primary_times_us']['after'][full] for short,full in [('State','State Monad'),('RowToList','RowToList'),('Church','Church Numerals')]}
output={'scope':'Mechanism prototype only; not compiler results or official samples','frozen_build':manifest['build'],'protocol':'3 processes forward/reverse/forward, original Bench_MeasureBatch, original calibration, minimum of ten then median of three; GOGC=800; metadata lookup outside timed batches; func()int64 metadata adapted to func()int','official_baseline_ns':reported,'summary':summary,'runs':runs,'oracles':{'timed_action_results':27,'variable_input_effect_checks':18,'preserved_apply_entry':27},'artifacts_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in HERE.iterdir() if p.is_file() and p.name!='results-preserve.json'}}
(HERE/'results-preserve.json').write_text(json.dumps(output,indent=2)+'\n')
print(json.dumps(summary,indent=2),flush=True)

