"""Pair original and unary-fallthrough runtime using identical action/adapter code."""
import hashlib,json,os,statistics,subprocess
from pathlib import Path
HERE=Path(__file__).resolve().parent
manifest=json.loads((HERE/'manifest.json').read_text())
def verify():
 for path,digest in manifest['original_files_sha256'].items():
  assert hashlib.sha256(Path(path).read_bytes()).hexdigest()==digest,path
verify()
env=dict(os.environ,GOGC='800');env.pop('GOMAXPROCS',None);env.pop('PPROF',None)
runs={'before':[],'after':[]};order=['before','after','after','before','before','after']
for index,runtime in enumerate(order,1):
 repetition=(index+1)//2
 result=subprocess.run([str(HERE/('probe-unary-'+runtime)),str(repetition)],capture_output=True,text=True,env=env,check=True,timeout=90)
 stem=f'unary-{index}-{runtime}'
 (HERE/(stem+'.stdout')).write_text(result.stdout);(HERE/(stem+'.stderr')).write_text(result.stderr)
 values=[json.loads(line) for line in result.stdout.splitlines()]
 assert len(values)==9 and all(v['actual']==v['expected'] for v in values)
 runs[runtime].append(values)
 print(stem+': 9 expected outputs and semantic checks passed',flush=True)
verify()
summary={}
for name in ['State','RowToList','Church']:
 summary[name]={}
 for variant in ['current','native-metadata','ordinary-preserved']:
  summary[name][variant]={}
  for runtime in ['before','after']:
   rows=[next(r for r in run if r['case']==name and r['variant']==variant) for run in runs[runtime]]
   summary[name][variant][runtime]={'median_ns':statistics.median(r['time_ns'] for r in rows),'process_ns':[r['time_ns'] for r in rows],'allocations_per_action':[r['allocations_per_action'] for r in rows]}
  summary[name][variant]['change_percent']=100*(summary[name][variant]['after']['median_ns']/summary[name][variant]['before']['median_ns']-1)
output={'scope':'Final isolated unary-runtime prototype; no compiler/benchmark/reference modified','protocol':'AB/BA/AB, three processes per runtime, same exact generated bodies and native int64-to-int metadata adapter; native resolution outside batches; original MeasureBatch/calibration/minimum of ten','source_patch':(HERE/'runtime-unary.patch').read_text(),'runs':runs,'summary':summary,'oracles':{'timed_expected_results':54,'capture_effect_checks':36,'preserved_entries':54,'extra_arguments_partials_nil':'passed in all six processes'},'frozen_sources_unchanged':True,'artifacts_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in HERE.iterdir() if p.is_file() and p.name!='results-unary.json'}}
(HERE/'results-unary.json').write_text(json.dumps(output,indent=2)+'\n')
print(json.dumps(summary,indent=2),flush=True)

