func AnyToValue(val any) Value {
	// The old ST FFI reads the reference envelope through this bridge too.
	// Return a Value copy so subsequent writes cannot change read snapshots.
	if cell, ok := val.(*stValueCell); ok {
		return cell.value
	}
	if val == nil {
		return Value{}
	}
	return Box(val)
}

